from cs_lib import *
C = 'Pre-Algebra (7th)'
CHK = lambda: L('Check Yourself', ['Did I follow the order of operations?', 'Did I do the same thing to both sides?', 'Did I check my answer in the original problem?', 'Does my answer have the right sign and units?'])

sheet('prealgebra7-algebraic-expressions-integers', C, 1, 'Algebraic Expressions and Integers',
  'place value, variables, expressions and the order of operations', 'integer operations, estimation, patterns and the coordinate plane',
  [V('Key Vocabulary', [['variable', 'A letter that stands for a number.', 'n in n + 7'], ['algebraic expression', 'Numbers, variables and operations, no equals sign.', '3x − 5'],
     ['integer', 'A whole number or its opposite.', '−8, 0, 15'], ['absolute value', 'Distance from 0.', '|−6| = 6'], ['opposites', 'Same distance from 0, opposite sides.', '7 and −7']]),
   EX('Order of Operations', 'Grouping, exponents, multiply/divide left to right, add/subtract left to right.', r'⟨20 - 3 \cdot 4 + 6 \div 2⟩', [['Multiply, divide:', '12 and 3'], ['Left to right:', '20 − 12 + 3']], '11', N('20-3*4+6/2', 11)),
   EX('Evaluating Expressions', 'Substitute, then simplify in order.', 'Evaluate 4a − b for a = 3, b = −2.', [['Substitute:', '4(3) − (−2) = 12 + 2']], '14', N('4*3-(-2)', 14)),
   W('Words to Expressions', [['7 less than a number', 'n − 7'], ['the product of 5 and a number', '5n'], ['a number divided by 3, plus 2', r'⟨\tfrac{n}{3} + 2⟩'], ['twice the sum of x and 4', '2(x + 4)']]),
   TB('Rounding and Estimating', ['Problem', 'Estimate'], [['4,872 rounded to the nearest hundred', '4,900'], ['398 + 512', '400 + 500 = 900'], ['61 × 19', '60 × 20 = 1,200']], 'Look at the digit to the right of the place you round to: 5 or more rounds up.', N('60*20', 1200)),
   MS('Quick Reminders & Common Mistakes', ['Multiply and divide before adding and subtracting.', 'A variable can stand for any number.', 'Estimate first, then check your exact answer against it.'],
      [['20 − 3 · 4 = 68', 'multiply first: 8'], ['|−6| = −6', '6'], ['“7 less than n” = 7 − n', 'n − 7']])],
  [TB('Adding and Subtracting Integers', ['Rule', 'Example'], [['Same signs: add, keep the sign', '−5 + (−3) = −8'], ['Different signs: subtract, take the sign of the larger absolute value', '−9 + 4 = −5'], ['Subtracting: add the opposite', '6 − (−2) = 6 + 2 = 8']],
      None, [N('-5+(-3)', -8), N('-9+4', -5), N('6-(-2)', 8)]),
   TB('Multiplying and Dividing Integers', ['Signs', 'Result'], [['same signs', 'positive: (−4)(−5) = 20'], ['different signs', 'negative: −24 ÷ 6 = −4'], ['even number of negatives', 'positive'], ['odd number of negatives', 'negative']], None, [N('(-4)*(-5)', 20), N('-24/6', -4)]),
   EX('Mixed Integer Problem', 'Use the order of operations with integer rules.', r'⟨-3(4 - 9) + (-12) \div 4⟩', [['Parentheses:', '−3(−5) = 15'], ['Divide:', '−12 ÷ 4 = −3']], '12', N('-3*(4-9)+(-12)/4', 12)),
   EX('Patterns and Inductive Reasoning', 'Find the rule from the examples, then extend it.', 'Next two terms: 3, 7, 11, 15, …', [['Rule:', 'add 4']], '19, 23', [N('15+4', 19), N('19+4', 23)]),
   TB('The Coordinate Plane', ['Quadrant', 'Signs'], [['I', '(+, +)'], ['II', '(−, +)'], ['III', '(−, −)'], ['IV', '(+, −)']], 'Start at the origin: move along x first, then y.'),
   CHK()])

sheet('prealgebra7-one-step-equations-inequalities', C, 2, 'Solving One-Step Equations and Inequalities',
  'number properties, the distributive property and simplifying', 'one-step equations and inequalities and their graphs',
  [TB('Properties of Numbers', ['Property', 'Example'], [['Commutative', 'a + b = b + a'], ['Associative', '(a + b) + c = a + (b + c)'], ['Identity', 'a + 0 = a, a · 1 = a'], ['Zero property', 'a · 0 = 0']]),
   EX('The Distributive Property', 'Multiply the outside number by EACH term inside.', '−3(2x − 5)', [['Distribute:', '−3 · 2x and −3 · (−5)']], '−6x + 15', {'expr': '-3*(2*x-5)', 'is': '-6*x+15'}),
   EX('Simplifying Expressions', 'Combine like terms: same variable, same exponent.', '5x + 8 − 2x + 3', [['Group:', '(5x − 2x) + (8 + 3)']], '3x + 11', {'expr': '5*x+8-2*x+3', 'is': '3*x+11'}),
   V('Key Vocabulary', [['like terms', 'Same variable part.', '4y and −y'], ['inverse operations', 'Undo each other.', '+ and −, × and ÷'], ['solution', 'Makes the equation true.', 'x = 4 for x + 3 = 7'],
     ['inequality', 'Compares with <, >, ≤, ≥.', 'n ≥ 2']]),
   EX('Guess, Check, and Revise', 'Make a guess, test it, and adjust up or down.', 'Two numbers add to 30 and one is 6 more than the other.', [['Try 10 and 20:', 'difference 10, too big'], ['Try 12 and 18:', 'difference 6 ✓']], '12 and 18', TRUE('12+18===30 && 18-12===6')),
   MS('Quick Reminders & Common Mistakes', ['Distribute to every term in the parentheses.', 'Only combine like terms.', 'Keep the sign in front of each term.'],
      [['−3(2x − 5) = −6x − 15', '+15 (negative × negative)'], ['5x + 3 = 8x', 'not like terms'], ['Dropping a negative sign', 'circle each sign first']])],
  [EX('Adding or Subtracting to Solve', 'Use the inverse operation on both sides.', 'x − 14 = −6', [['Add 14:', 'x = −6 + 14']], 'x = 8', N('-6+14', 8)),
   EX('Multiplying or Dividing to Solve', 'Divide (or multiply) both sides.', r'⟨\tfrac{y}{-4} = 7⟩', [['Multiply by −4:', 'y = 7(−4)']], 'y = −28', N('7*(-4)', -28)),
   W('Graphing Inequalities', [['x > −2', 'open circle at −2, shade right'], ['x ≤ 5', 'closed circle at 5, shade left'], ['n ≥ 0', 'closed circle at 0, shade right']]),
   EX('Inequalities by Adding or Subtracting', 'Solve like an equation; the sign does not change.', 'n + 9 ≤ 4', [['Subtract 9:', 'n ≤ −5']], 'n ≤ −5', TRUE('-5+9 <= 4 && !(-4.9+9 <= 4)')),
   EX('Inequalities by Multiplying or Dividing', 'Dividing or multiplying by a NEGATIVE flips the inequality sign.', '−3x < 12', [['Divide by −3 and flip:', 'x > −4']], 'x > −4', TRUE('-3*(-3.9) < 12 && !(-3*(-4) < 12)')),
   CHK()])

sheet('prealgebra7-decimals-equations', C, 3, 'Decimals and Equations',
  'rounding, estimating and measures of center', 'formulas, decimal equations and the metric system',
  [EX('Rounding Decimals', 'Find the place, look one digit to the right: 5 or more rounds up.', 'Round 6.4782 to the nearest hundredth.', [['Hundredths digit:', '7; next digit 8 rounds up']], '6.48', N('Math.round(6.4782*100)/100', 6.48)),
   EX('Estimating Products and Quotients', 'Round to compatible numbers first.', 'Estimate 39.6 × 5.1 and 63.5 ÷ 8.2.', [['Round:', '40 × 5 and 64 ÷ 8']], '≈ 200 and ≈ 8', [N('40*5', 200), N('64/8', 8)]),
   TB('Measures of Center', ['Measure', 'How to find it'], [['Mean', 'sum ÷ number of values'], ['Median', 'middle value of ordered data'], ['Mode', 'most frequent value']], 'Data 2.5, 3, 3, 4.5: mean 3.25, median 3, mode 3', N('(2.5+3+3+4.5)/4', 3.25)),
   EX('Mean of Decimal Data', 'Add, then divide by the count.', 'Times: 12.4, 11.8, 13.1, 12.7 s', [['Sum:', '50.0'], ['Divide by 4:', '12.5']], '12.5 s', N('(12.4+11.8+13.1+12.7)/4', 12.5)),
   EX('Using Formulas', 'Substitute the known values into the formula.', 'd = rt with r = 55.5 mph, t = 2.4 h', [['Multiply:', '55.5 × 2.4']], '133.2 miles', N('55.5*2.4', 133.2)),
   MS('Quick Reminders & Common Mistakes', ['Line up decimal points to add or subtract.', 'Count decimal places when multiplying.', 'An outlier changes the mean more than the median.'],
      [['Rounding 6.4782 to 6.47', 'the 8 rounds the 7 up: 6.48'], ['Median of unordered data', 'order first'], ['Forgetting units in formulas', 'write units every step']])],
  [EX('Adding or Subtracting Decimals', 'Undo the operation on both sides.', 'x + 3.75 = 10.2', [['Subtract 3.75:', 'x = 10.2 − 3.75']], 'x = 6.45', N('10.2-3.75', 6.45)),
   EX('Multiplying or Dividing Decimals', 'Divide both sides by the coefficient.', '1.6m = 9.6', [['Divide:', r'⟨m = \tfrac{9.6}{1.6}⟩']], 'm = 6', N('9.6/1.6', 6)),
   EX('Division Equations', 'Multiply both sides by the divisor.', r'⟨\tfrac{k}{0.4} = 15⟩', [['Multiply by 0.4:', 'k = 15 × 0.4']], 'k = 6', N('15*0.4', 6)),
   TB('Metric Prefixes', ['Prefix', 'Meaning'], [['kilo- (k)', '1,000'], ['centi- (c)', r'⟨\tfrac{1}{100}⟩'], ['milli- (m)', r'⟨\tfrac{1}{1000}⟩']], 'Bigger unit → smaller unit: multiply. Smaller → bigger: divide.'),
   TB('Metric Conversions', ['Convert', 'Answer'], [['3.2 km to m', '3,200 m'], ['450 cm to m', '4.5 m'], ['2.5 L to mL', '2,500 mL'], ['760 mg to g', '0.76 g']], None, [N('3.2*1000', 3200), N('450/100', 4.5), N('760/1000', 0.76)]),
   CHK()])

sheet('prealgebra7-factors-fractions-exponents', C, 4, 'Factors, Fractions, and Exponents',
  'divisibility, prime factorization, GCF and simplifying fractions', 'rational and irrational numbers, exponent rules, scientific notation and cube roots',
  [TB('Divisibility Rules', ['Divisible by', 'If …'], [['2', 'the last digit is even'], ['3', 'the digit sum is divisible by 3'], ['5', 'the last digit is 0 or 5'], ['9', 'the digit sum is divisible by 9'], ['10', 'the last digit is 0']]),
   EX('Prime Factorization', 'Use a factor tree until every branch ends in a prime.', 'Prime factorization of 72', [['Tree:', '72 = 8 · 9 = 2 · 2 · 2 · 3 · 3']], r'⟨2^3 \cdot 3^2⟩', N('2**3*3**2', 72)),
   EX('Greatest Common Factor', 'Multiply the primes the numbers share.', 'GCF of 36 and 60', [['Primes:', r'⟨36 = 2^2 \cdot 3^2⟩, ⟨60 = 2^2 \cdot 3 \cdot 5⟩'], ['Shared:', r'⟨2^2 \cdot 3⟩']], '12', N('2**2*3', 12)),
   EX('Simplifying Fractions', 'Divide the numerator and denominator by their GCF.', r'Simplify ⟨\tfrac{36}{60}⟩.', [['Divide by 12:', r'⟨\tfrac{3}{5}⟩']], r'⟨\tfrac{3}{5}⟩', N('36/60', 0.6)),
   V('Key Vocabulary', [['prime', 'Exactly two factors: 1 and itself.', '2, 3, 5, 7, 11'], ['composite', 'More than two factors.', '4, 9, 12'], ['rational', 'Can be written as a fraction of integers.', r'⟨-\tfrac{2}{3}⟩, 0.25'], ['irrational', 'Non-ending, non-repeating decimal.', r'⟨\sqrt{2}⟩, π']]),
   MS('Quick Reminders & Common Mistakes', ['1 is neither prime nor composite.', 'Use exponents to group repeated prime factors.', r'⟨\sqrt{n}⟩ is irrational unless n is a perfect square.'],
      [['Calling 51 prime', '51 = 3 · 17'], ['GCF = product of all primes', 'only the shared ones'], [r'Writing ⟨\tfrac{36}{60} = \tfrac{6}{10}⟩ as final', 'keep dividing: ⟨\\tfrac{3}{5}⟩']])],
  [TB('Exponent Rules', ['Rule', 'Example'], [[r'⟨a^m \cdot a^n = a^{m+n}⟩', r'⟨x^3 \cdot x^4 = x^7⟩'], [r'⟨\tfrac{a^m}{a^n} = a^{m-n}⟩', r'⟨\tfrac{5^6}{5^2} = 5^4⟩'], [r'⟨a^0 = 1⟩', r'⟨9^0 = 1⟩'], [r'⟨a^{-n} = \tfrac{1}{a^n}⟩', r'⟨2^{-3} = \tfrac{1}{8}⟩']], None, [N('5**6/5**2', 625), N('2**-3', 0.125)]),
   EX('Exponents and Multiplication', 'Multiply coefficients and add exponents of the same base.', r'⟨(3x^2)(4x^5)⟩', [['Coefficients:', '3 · 4 = 12'], ['Exponents:', '2 + 5 = 7']], r'⟨12x^7⟩', {'expr': '(3*x**2)*(4*x**5)', 'is': '12*x**7'}),
   EX('Exponents and Division', 'Divide coefficients and subtract exponents.', r'⟨\tfrac{18y^9}{6y^3}⟩', [['Divide:', '18 ÷ 6 = 3'], ['Subtract:', '9 − 3 = 6']], r'⟨3y^6⟩', {'expr': '18*y**9/(6*y**3)', 'is': '3*y**6'}),
   TB('Scientific Notation', ['Standard form', 'Scientific notation'], [['5,600,000', r'⟨5.6 \times 10^6⟩'], ['0.00043', r'⟨4.3 \times 10^{-4}⟩'], ['72,000', r'⟨7.2 \times 10^4⟩']], r'⟨a \times 10^n⟩ with ⟨1 \le a < 10⟩.', [N('5.6e6', 5600000), N('4.3e-4', 0.00043)]),
   TB('Cube Roots', ['Find', 'Answer'], [[r'⟨\sqrt[3]{64}⟩', '4'], [r'⟨\sqrt[3]{-125}⟩', '−5'], [r'⟨x^3 = 27⟩', 'x = 3'], [r'⟨\sqrt[3]{\tfrac{8}{27}}⟩', r'⟨\tfrac{2}{3}⟩']], 'A negative number has a negative cube root.', [N('Math.cbrt(64)', 4), N('Math.cbrt(-125)', -5)]),
   CHK()])

