   EX('Similar Figures', 'Corresponding sides are proportional.', 'Sides 4 and 6 in one figure; the matching side to 4 is 10. Find x matching 6.', [['Scale factor:', r'⟨\tfrac{10}{4} = 2.5⟩']], 'x = 15', N('6*10/4', 15)),
